style.css:
@-moz-document domain("roblox.com") {
html, body {
        height: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        background-image: url("https://64.media.tumblr.com/dc84abc5a20f4949624a0f77e5be011d/tumblr_n2drz6w7ZA1tnr0q8o1_1280.jpg") !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
        background-size: cover !important;
        background-attachment: fixed !important;
    }

    /* Make all major areas transparent so background shows */
    .container-main,
    .rbx-body,
    .content,
    .rbx-main-content,
    .rbx-navbar,
    .footer,
    .games-page,
    .game-card,
    .section,
    .theme-dark {
        background: transparent !important;
        box-shadow: none !important;
        border: none !important;
    }

    /* Optional: readable text + nice link colors */
    body, .text, span, p, div {
        color: #ffffff !important;
    }

    a {
        color: #ffaad4 !important; /* soft pink */
    }
}
